#pragma once
#include "ksMonoArpTask.h"
#include "ksPartControlTasks.h"
#include "ksMidiFileTimeService.h"
#include "ksNativeMonoArpBootstrapService.h"
#include <array>
#include <optional>
#include <stdexcept>
#include <type_traits>
namespace ks {
// Live mono-pattern transaction. The enclosing native work graph owns typed
// decoder/file children. Requests never name code addresses or CPU operands.
class NativeMonoArpCoordinator final {
public:
 using Kind=MonoArpTask::Kind;using OutcomeHandle=uint32_t;static constexpr OutcomeHandle NoOutcome=~0u;
 enum class Component{Event,Lookup,Time,Output};enum class Notice{Policy,Lookup,Time,Output};struct Noop{template<class...A>void operator()(A&&...)const{}};enum class Request{None,InternalDecode,FileStart,FileContinue};
 struct Context{uint32_t expressionSource=0;uint8_t activation=0;};
 struct Input{uint32_t record=0,stream=0;uint8_t byte=0;Context context{};};
 struct ChildInput{uint32_t record=0,stream=0;uint8_t byte=0;Context context{};};
 struct ChildResult{OutcomeHandle outcome=NoOutcome;uint32_t stream=0,record=0,expressionSource=0,expressionSourceMask=0;uint8_t activation=0;bool expressionKnown=false,activationKnown=false,recordKnown=false;};
 struct Effect{bool read=false,write=false;};
 struct Result{uint32_t stream=0,record=0,phase=0,deadline=0,delta=0;Context context{};uint64_t internalCalls=0,fileCalls=0;OutcomeHandle lastInternal=NoOutcome,lastFile=NoOutcome;uint8_t remaining=0,skip=0;bool due=false,delayed=false,output=false;};
 NativeMonoArpCoordinator(Kind k,Input i):kind_(k),input_(i){if(k!=Kind::Service&&k!=Kind::Event&&k!=Kind::Send&&k!=Kind::Meta)throw std::logic_error("Mono bootstrap belongs to closed Bootstrap service");result_.context=i.context;push(k,i.record,i.stream,i.byte);}
 Kind kind()const{return kind_;}const Input&input()const{return input_;}const Result&result()const{return result_;}bool complete()const{return !depth_;}bool critical()const{return false;}Component component()const{return component_;}Request request()const{return request_;}const ChildInput&childInput()const{return child_;}const Effect&effect()const{return effect_;}const PartLookupTask*lookup()const{return lookup_?&*lookup_:nullptr;}const MidiFileTimeService*time()const{return time_?&*time_:nullptr;}const NativeMonoArpBootstrapService*output()const{return output_?&*output_:nullptr;}
 bool resumeInternal(ChildResult r){if(request_!=Request::InternalDecode)return false;merge(r);result_.lastInternal=r.outcome;++result_.internalCalls;request_=Request::None;current().task.resumeChild();return true;}
 bool resumeFile(ChildResult r){if(request_!=Request::FileStart&&request_!=Request::FileContinue)return false;if(!r.recordKnown)throw std::logic_error("Missing returned file data binding");merge(r);result_.lastFile=r.outcome;++result_.fileCalls;request_=Request::None;finish(r.stream,r.record);return true;}
 template<class T>const T*task()const{if constexpr(std::is_same_v<T,MonoArpTask>)return component_==Component::Event&&depth_?&current().task:nullptr;else if constexpr(std::is_same_v<T,PartLookupTask>)return component_==Component::Lookup?&*lookup_:nullptr;else if constexpr(std::is_same_v<T,MidiFileTimeService>)return component_==Component::Time?&*time_:nullptr;else if constexpr(std::is_same_v<T,NativeMonoArpBootstrapService>)return component_==Component::Output?&*output_:nullptr;else {if(component_==Component::Time)return time_->template task<T>();if(component_==Component::Output)return output_->template task<T>();return nullptr;}}
 unsigned nextClocks(int previous=-1,int previousRead=-1)const{if(complete()||request_!=Request::None)return 0;if(component_==Component::Lookup)return lookup_->stage()==PartLookupTask::Stage::Complete?17:lookup_->nextClocks();if(component_==Component::Time)return time_->nextClocks(previous,previousRead);if(component_==Component::Output)return output_->nextClocks(previous);return current().task.nextClocks(bus(current().task,previous));}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1,int previousRead=-1){return advanceObservedBefore(budget,read,write,Noop{},previous,previousRead);}
 template<class R,class W,class O>unsigned advanceObservedBefore(unsigned budget,R&&read,W&&write,O&&observe,int previous=-1,int previousRead=-1){const auto cost=nextClocks(previous,previousRead);if(!cost||cost>budget)return 0;return advancePlannedPhase(cost,read,write,observe,previous,previousRead);}
private:
 template<class>friend class NativeMonoArpOwnedGraph;
 friend class NativeArpMainService;
 // The owner synchronously passes this phase's admitted nonzero cost.
 template<class R,class W,class O>unsigned advancePlannedPhase(unsigned cost,R&&read,W&&write,O&&observe,int previous=-1,int previousRead=-1){effect_={};const auto notify=[&](Notice n,MonoArpTask::Stage stage,const MonoArpTask&t){static_assert(std::is_void_v<decltype(observe(n,stage,*this,t))>);observe(n,stage,*this,t);};
 if(component_==Component::Lookup){if(lookup_->stage()==PartLookupTask::Stage::Complete){effect_.read=true;notify(Notice::Lookup,current().task.stage(),current().task);current().task.resumePart(0x160d2u+334*lookup_->index());component_=Component::Event;}else lookup_->advanceBefore(cost,[&](PartLookupTask::Layout){return read(0x17526,cost);});return cost;}
 if(component_==Component::Time){time_->advanceBefore(cost,read,write,previous,previousRead);effect_={time_->effect().read,time_->effect().write};if(time_->complete()){notify(Notice::Time,current().task.stage(),current().task);result_.delayed=true;result_.delta=time_->summary().value;result_.deadline=time_->summary().published;result_.context.expressionSource=time_->summary().value;current().task.resumeDelay(time_->summary().stream);component_=Component::Event;}return cost;}
 if(component_==Component::Output){output_->advanceBefore(cost,read,write,previous);effect_={output_->effect().read,output_->effect().write};if(output_->complete()){notify(Notice::Output,current().task.stage(),current().task);result_.output=true;const auto*m=output_->masks();if(m){const auto&t=m->maskTask();const auto&v=m->summary();result_.context.activation=uint8_t(v.ran?(v.changed?t.other():t.mask()):result_.context.activation);}current().task.resumeChild();component_=Component::Event;}return cost;}
 using T=MonoArpTask;using S=T::Stage;auto&f=current();auto&t=f.task;const auto stage=t.stage();
 const auto get=[&](uint32_t raw,unsigned width,unsigned post=0,bool stream=false){if(!(stream?MidiFileTimeService::streamReadable(raw,width):MidiFileTimeService::readable(raw,width)))throw std::logic_error("Unsupported mono stream/time observation");const auto a=raw&0xffffff;const auto total=wide(a,width,-1);unsigned dt=cost-post-total;int p=-1;uint32_t v=0;for(unsigned n=0;n<width;++n){dt+=byte(a+n,p);p=int(a+n);v=(v<<8)|uint8_t(read((a+n)&0xffffff,dt));}return v;};
 t.advanceBefore(cost,[&](S q)->uint32_t{switch(q){case S::ServiceReadStream:return get(t.timeRecord()+52,4);case S::ServiceReadDeadline:return result_.deadline=get(t.timeRecord()+56,4);case S::ServiceReadPhase:{const auto v=get(t.timeRecord()+60,4);result_.phase=v;result_.context.activation=uint8_t(v>>8);return v;}case S::EventRead:case S::EventReadData:case S::MetaRead:return get(t.stream(),1,2,true);case S::MetaReadSkip:return result_.skip=uint8_t(get(t.stream(),1,2,true));case S::EventReadStatusCount:case S::EventReadDataCount:return result_.remaining=uint8_t(get(0x15c2c,1));case S::MetaReadStream:return get(t.timeRecord()+48,4);default:throw std::logic_error("Unknown mono observation");}},[&](S q,uint32_t v){if(q!=S::ServicePublishCursor)throw std::logic_error("Unknown mono publication");const auto a=(t.timeRecord()+52)&0xffffff;if(!MidiFileTimeService::writable(a,4))throw std::logic_error("Unsupported mono cursor binding");unsigned dt=cost-wide(a,4,previous);int p=previous;for(unsigned n=0;n<4;++n){dt+=byte(a+n,p);p=int(a+n);write((a+n)&0xffffff,uint8_t(v>>(24-8*n)),dt);}},[&](S){return bus(t,previous);});
 if(stage==S::EventTickCount)--result_.remaining;notify(Notice::Policy,stage,t);
 switch(stage){case S::ServiceBindPart:case S::ServiceRetainPart:case S::ServiceEvent:case S::ServiceDelay:case S::EventStatus:case S::EventRetainCount:case S::EventSendData:case S::SendRetainPart:case S::SendRetainStream:case S::SendDecode:case S::MetaOutput:effect_.write=true;break;case S::ServiceRestorePart:case S::ServiceFinish:case S::EventReleaseCount:case S::EventFinish:case S::SendRestoreStream:case S::SendRestorePart:case S::SendFinish:case S::MetaFinish:case S::MetaEndFinish:effect_.read=true;break;default:break;}
 if(t.handoff()){child_={t.timeRecord(),t.stream(),t.byte(),result_.context};request_=t.route()==T::Route::ExternalStart?Request::FileStart:Request::FileContinue;}
 else if(t.awaitingChild()){switch(t.child()){case T::Child::BindPart:lookup_.emplace(PartLookupTask::Layout::Parameters);component_=Component::Lookup;break;case T::Child::Event:result_.due=true;push(Kind::Event,t.timeRecord(),t.stream(),t.byte());break;case T::Child::Send:push(Kind::Send,t.timeRecord(),t.stream(),t.byte());break;case T::Child::Decode:child_={t.timeRecord(),t.stream(),t.byte(),result_.context};request_=Request::InternalDecode;break;case T::Child::Delay:if(!MidiFileTimeService::writable(t.timeRecord()+56,4))throw std::logic_error("Native mono delay refuses an executable or non-writable deadline record");time_.emplace(MidiFileTimeService::Kind::ArpDelay,MidiFileTimeService::Input{t.stream(),0,t.timeRecord()});component_=Component::Time;break;case T::Child::Output:output_.emplace(NativeMonoArpBootstrapService::Kind::Output,NativeMonoArpBootstrapService::Input{t.timeRecord(),t.stream()});component_=Component::Output;break;default:throw std::logic_error("Unclosed native mono child");}}
 else if(t.complete())finish(t.stream(),t.timeRecord());return cost;
 }
public:
 uint32_t expressionSourceAfter(uint32_t)const{if(!complete())throw std::logic_error("Incomplete mono source");return result_.context.expressionSource;}uint8_t activationAfter(uint8_t)const{if(!complete())throw std::logic_error("Incomplete mono activation");return result_.context.activation;}
private:
 struct Frame{Kind kind;MonoArpTask task;Frame(Kind k,uint32_t record,uint32_t stream,uint8_t b):kind(k),task(k,record,stream,b){}};
 Frame&current(){return *frames_[depth_-1];}const Frame&current()const{return *frames_[depth_-1];}
 void push(Kind k,uint32_t record,uint32_t stream,uint8_t b){if(depth_==frames_.size())throw std::logic_error("Mono continuation depth exceeded");frames_[depth_++].emplace(k,record,stream,b);component_=Component::Event;}
 void finish(uint32_t stream,uint32_t record){--depth_;if(depth_){auto&p=current().task;if(p.child()==MonoArpTask::Child::Event)p.resumeEvent(stream,record);else p.resumeChild();}else{result_.stream=stream;result_.record=record;}component_=Component::Event;}
 void merge(const ChildResult&r){const auto mask=r.expressionKnown?0xffffffffu:r.expressionSourceMask;result_.context.expressionSource=(result_.context.expressionSource&~mask)|(r.expressionSource&mask);if(r.activationKnown)result_.context.activation=r.activation;}
 static unsigned byte(uint32_t a,int p){a&=0xffffff;return a<0x400000&&!(p&1)&&a==(uint32_t(p)|1u)?0:3;}
 static unsigned wide(uint32_t a,unsigned n,int p){unsigned c=0;for(unsigned i=0;i<n;++i){c+=byte((a+i)&0xffffff,p);p=int((a+i)&0xffffff);}return c;}
 static unsigned bus(const MonoArpTask&t,int previous){using S=MonoArpTask::Stage;switch(t.stage()){case S::ServiceReadStream:return wide(t.timeRecord()+52,4,-1);case S::ServiceReadDeadline:return wide(t.timeRecord()+56,4,-1);case S::ServiceReadPhase:return wide(t.timeRecord()+60,4,-1);case S::ServicePublishCursor:return wide(t.timeRecord()+52,4,previous);case S::MetaReadStream:return wide(t.timeRecord()+48,4,-1);case S::EventRead:case S::EventReadData:case S::MetaRead:case S::MetaReadSkip:case S::EventReadStatusCount:case S::EventReadDataCount:return 3;default:return 0;}}
 Kind kind_;Input input_;Result result_{};Effect effect_{};Request request_=Request::None;ChildInput child_{};Component component_=Component::Event;unsigned depth_=0;std::array<std::optional<Frame>,3>frames_{};std::optional<PartLookupTask>lookup_;std::optional<MidiFileTimeService>time_;std::optional<NativeMonoArpBootstrapService>output_;
};
}
